import{c as t,Q as a,j as n,m as i}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Change history and pipeline replication","description":"","frontmatter":{},"headers":[],"relativePath":"pipeline/guide/concepts/change-tracking-and-pipeline.md","filePath":"pipeline/guide/concepts/change-tracking-and-pipeline.md","lastUpdated":1779484536000}'),r={name:"pipeline/guide/concepts/change-tracking-and-pipeline.md"};function s(o,e,l,c,p,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="change-history-and-pipeline-replication" tabindex="-1">Change history and pipeline replication <a class="header-anchor" href="#change-history-and-pipeline-replication" aria-label="Permalink to &quot;Change history and pipeline replication&quot;">​</a></h1><p><strong><code>@cap-js/change-tracking</code></strong> records who changed what on entities you annotate for end-user auditing and UI “change history” features. <strong><code>cds-data-pipeline</code></strong> fills tables from remote sources and records <strong>per-run</strong> statistics on <code>Pipelines</code> / <code>PipelineRuns</code> (created, updated, deleted counts, watermarks, errors).</p><p>These concerns are <strong>orthogonal</strong>:</p><ul><li>Pipeline runs attribute bulk sync work to a <strong>run</strong> and a <strong>pipeline name</strong>, not to interactive user edits on individual fields.</li><li>Change tracking attributes <strong>row-level</strong> changes to <strong>business users</strong> when they edit data through your app.</li></ul><p>After a replicate run, rows in the target table match the remote slice you defined (consumption view, delta mode). Local <strong>enrichment</strong> columns (fields not overwritten by the pipeline’s UPSERT strategy) can still be edited by users; keep pipeline mapping and delta configuration aligned with what you want to preserve vs overwrite.</p><p>For pipeline observability, use the <a href="./../../reference/management-service.html">Management Service</a> and <a href="./../../reference/features.html#observability">Features → Observability</a> rather than treating <code>PipelineRuns</code> statistics as a substitute for <code>@cap-js/change-tracking</code>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./consumption-views.html">Consumption views</a> — local shape and what the pipeline writes.</li><li><a href="./../recipes/built-in-replicate.html#what-happens-at-runtime">Built-in replicate → What happens at runtime</a> — READ / MAP / WRITE and tracker updates.</li></ul>',8)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
